    stich: ['TRIAC', 'Dimmer', 'Phasenanschnitt', 'Wechselstromschalter', 'Halbleiterrelais', 'SSR', 'Zündimpuls'],
    alias: ['TRIAC'], speak: 'TRIAC', pruef: 2, status: 'entwurf'
