    stich: ['Varistor', 'VDR', 'Überspannungsschutz', 'Zinkoxid', 'MOV', 'Ableiter', 'Stoßstrom'],
    alias: ['VDR'], speak: 'VDR', pruef: 1, status: 'frage', frage: 'wiki__F4'
