    labs: ['loch', 'sch', 'sim', 'haus', 'sps', 'code', 'ant'],
    stich: ['Relais', 'Relay', 'Schütz', 'Schließer', 'Öffner', 'Wechsler', 'Spule', 'Freilaufdiode', 'galvanische Trennung', 'K1'],
